{
  if (!a->ae_auto)
    {
      return CAMENC_3A_ST_MANUAL;
    }

  if (!a->settled)
    {
      return CAMENC_3A_ST_MOVING;
    }

  return camenc_3a_at_target(a) ? CAMENC_3A_ST_SETTLED : CAMENC_3A_ST_RANGE;
}

